// TH14 v1.00b Extra st07.ecl MainSub08 (source 991-1004), GirlC01 (343-365),
// GirlC01_at (367-398). source="th14", rank 4 only.
// Source type5 -> TH14_BALL2, color 2 (transcribe/th14/bullet-types.md).

const TH14_BALL2: int = 432;

const TIME_LIMIT: int = 1624;   // 120 buffer + 1500 schedule/tail estimate + 4 startup
const OPENING_BUFFER: int = 120;
const GIRL_HP: int = 800;       // enmCreate hp

// RANDF  -> (rand(16384) as fx)/16384fx, [0,1) at 1/16384 step
// RANDRAD -> (rand(65536)-32768) as angle, [-pi,pi) as BAM

// GirlC01_at (source 367-398): 180 schedule steps, 5 shots per step.
async sub girl_bullets() {
    // %C = %RANDRAD (379)
    var c: angle = (rand(65536) - 32768) as angle;
    for step in 0..180 {
        // circlePos(%A,%B,%C,%RANDF*64) (383)
        var u: fx = (rand(16384) as fx) / 16384fx;
        var radius: fx = u * 64fx;
        var ca: fx = radius * cos(c);
        var cb: fx = radius * sin(c);
        // etOffsetAbs with FINAL_X/Y (384): snapshot enemy position for this step
        var sx: fx = $self_x;
        var sy: fx = $self_y;
        // etAngle(0,%RANDRAD,0) under aim mode 3 / count 1 (385)
        var base: angle = (rand(65536) - 32768) as angle;
        for k in 0..5 {
            // etOffsetRad(0,%RANDRAD,%RANDF*8) (389)
            var th: angle = (rand(65536) - 32768) as angle;
            var v: fx = (rand(16384) as fx) / 16384fx;
            var r: fx = v * 8fx;
            // birth ANIM keeps position -= 4*velocity (speed 1.5 -> 6px back)
            var x: fx = sx + ca + r * cos(th) - 6fx * cos(base);
            var y: fx = sy + cb + r * sin(th) - 6fx * sin(base);
            _ = fire(TH14_BALL2, 2, x, y, 1.5fx, base, none, none);
        }
        // %C = %C + ((pi/2)*%RANDF + pi/4) (393)
        var w: fx = (rand(16384) as fx) / 16384fx;
        c = c + (((w * 16384fx) as int + 8192) as angle);
        wait(2);
    }
}

async sub girl_main() {
    set_invuln(65535);
    set_hitbox(8fx);    // setHitbox(16,16), radius 16*0.5
    set_hurtbox(12fx);  // setHurtbox(24,24), radius 24*0.5
    move_vel(0, 90deg, 1.5fx, EASE_LINEAR);              // moveVel(pi/2, 1.5) (353)
    move_vel(80, aim_player(), 0.1fx, EASE_QUAD_IN);     // moveVelTime(80,1,ANGLE_PLAYER,0.1) (354)
    wait(60);
    spawn girl_bullets();                                // @GirlC01_at() async (356)
    wait(200);
    move_vel(80, 90deg, 1.0fx, EASE_QUAD_IN);            // moveVelTime(80,1,pi/2,1.0) (358)
    loop { wait(1000); }                                 // infinite wait(1000) loop (360-363)
}

// MainSub08 (991-1004): 7x GirlC01, created relative to the stage origin.
async sub wave_pattern() {
    wait(OPENING_BUFFER);
    _ = spawn_enemy(0fx, -32fx, GIRL_HP, 0, 0, 0, girl_main);
    _ = spawn_enemy(-128fx, -32fx, GIRL_HP, 0, 0, 0, girl_main);
    _ = spawn_enemy(128fx, -32fx, GIRL_HP, 0, 0, 0, girl_main);
    wait(160);
    _ = spawn_enemy(32fx, -32fx, GIRL_HP, 0, 0, 0, girl_main);
    _ = spawn_enemy(-32fx, -32fx, GIRL_HP, 0, 0, 0, girl_main);
    wait(160);
    _ = spawn_enemy(-128fx, -32fx, GIRL_HP, 0, 0, 0, girl_main);
    wait(160);
    _ = spawn_enemy(0fx, -32fx, GIRL_HP, 0, 0, 0, girl_main);
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, wave_pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
